insert into public.values_library
  (slug, name, element, essence, light, shadow, void, pillars, balancing_kin, nourishing_kin, synonyms)
values
  ('acceptance', 'Acceptance', 'Water', 'Letting what is be here, so you can meet it with open eyes.', 'Acceptance is the moment you stop wrestling the wave and learn to float. It doesn''t mean you like what''s happening, or that you''ll never change it. In practice, it means acknowledging reality as it is right now, including your own feelings and limits. From that honest ground, wise action becomes possible.', 'Too much, and acceptance slides into resignation. "That''s just how it is" can become a reason never to try, never to speak up, never to leave. Floating turns into drifting somewhere you never chose.', 'Without acceptance, life becomes a long argument with what already is. Energy pours into resisting, blaming, or wishing things were otherwise. Beneath the struggle there''s often grief waiting for permission to be felt.', '{"Heart","Spirit"}', '{"courage"}', '{"presence","patience"}', '{"allowing","equanimity of heart"}'),
  ('adaptability', 'Adaptability', 'Water', 'Like water, finding a way around the stone.', 'Adaptability is the grace of changing shape without losing yourself. Water fits whatever vessel it''s poured into and still stays water. In everyday terms, it''s adjusting your plans, habits or views when life shifts, rather than breaking against it. It lets you meet change as a doorway rather than a threat.', 'Too much, and you become whatever each room needs you to be. Constant bending can leave you unsure what you actually want, think or believe. A river with no banks becomes a flood, or a swamp.', 'Without adaptability, life feels brittle. Every change lands like a crack, and plans become cages you defend. Rigidity often grows from times when change meant danger. Small, safe experiments in flexibility can soften it.', '{"Mind","Heart"}', '{"integrity"}', '{"openness","resilience"}', '{"fluidity","versatility"}'),
  ('comfort', 'Comfort', 'Water', 'Being a soft place to land, for others and yourself.', 'Comfort is a warm blanket on a cold night, a cup of tea held in both hands. It''s the feeling of safety and ease, and the gift of offering that to others. Comfort in practice is a cosy corner, a hug that lasts, a friend who sits with you without trying to fix anything.', 'Too much, and comfort can keep you small. The comfort zone becomes a cage, and anything new or uncertain starts to feel like a threat. Comfort can also slide into numbing: soothing yourself so constantly that you never feel what needs feeling.', 'Without comfort, life feels exposed and cold. You may struggle to soothe yourself when you''re upset, or feel you have to be strong all the time. Comforting yourself is a skill, and it''s never too late to learn it.', '{"Home & Earth","Heart"}', '{"courage"}', '{"rest","compassion"}', '{"solace","ease"}'),
  ('compassion', 'Compassion', 'Water', 'A warm hand held out to suffering, your own included.', 'Compassion is the heart turning toward pain instead of away from it. Like a lantern carried into a dark room, it doesn''t make the darkness vanish, but no one has to sit there alone. In plain terms: you notice when someone is hurting, and you let that move you to care, gently and without judgement. It begins at home, in the way you speak to yourself on hard days.', 'Too much, and the lantern-bearer forgets to rest. Compassion can tip into rescuing, fixing, or carrying other people''s lives as if they were yours. You might care for everyone but yourself, and call the exhaustion love.', 'When compassion runs dry, the heart grows a hard shell. Others'' pain starts to feel like an inconvenience, and your own like a weakness. Often the well hasn''t gone dry, it''s been overdrawn. Tending yourself is usually how it fills again.', '{"Heart","Connection"}', '{"boundaries"}', '{"empathy","forgiveness"}', '{"warmth","mercy"}'),
  ('empathy', 'Empathy', 'Water', 'The capacity to feel into another''s world, and to come back to your own.', 'Empathy is stepping into the river of someone else''s feeling and letting it move around you for a while. You sense what they''re carrying before they find the words. In plain terms: understanding and sharing another person''s feelings, and letting them know they''re not alone in them. People feel less alone near you, not because you fix anything, but because you were willing to feel it with them.', 'Too much, and you start carrying what isn''t yours. Other people''s moods become your weather. You may lose track of where their pain ends and your own begins, and give until you''re empty, then wonder why you feel so tired around people you love.', 'When empathy goes missing, other people can start to feel like obstacles or noise. Often this isn''t coldness so much as exhaustion, or an old need to protect a heart that once felt too much. The absence can point to where your own feelings have gone unheard.', '{"Connection","Heart"}', '{"boundaries"}', '{"compassion","presence"}', '{"attunement","fellow-feeling"}'),
  ('forgiveness', 'Forgiveness', 'Water', 'Setting down a stone you were never meant to carry forever.', 'Forgiveness is loosening your grip on a hurt so it stops steering your days. Like a river that slowly smooths a sharp stone, it often happens gradually, not in one grand gesture. Literally: you stop demanding that the past be different, and choose to free yourself from carrying it. Forgiving isn''t forgetting, and it doesn''t require reunion. It is mostly a gift to your own heart.', 'Rushed or forced, forgiveness can skip over what needed to be felt. You might forgive so quickly that harm is never named, or keep returning to people who keep hurting you. Peace-keeping can masquerade as peace.', 'Without forgiveness, old wounds stay open and keep getting pressed. Resentment becomes a heavy coat you wear in every season. Sometimes that anger is protecting something precious; honouring it is part of the path to setting it down.', '{"Heart"}', '{"fairness"}', '{"compassion","acceptance"}', '{"pardon","mercy"}'),
  ('generosity', 'Generosity', 'Water', 'Giving freely, from fullness.', 'Generosity is a spring that keeps flowing because it isn''t hoarded. It''s sharing your time, attention, resources and warmth without keeping score. True generosity comes from fullness rather than obligation, and it often gives as much to the giver as to the one receiving.', 'Too much, and generosity can empty you out. Giving becomes a way to be liked, to avoid conflict, or to feel worthy, until there''s nothing left for you. Giving that leaves you resentful has often crossed into self-abandonment.', 'Without generosity, life can feel tight and guarded. You might hold on to what you have in case there won''t be enough, or find it hard to give without expecting something back. Scarcity often grows from times when there truly wasn''t enough.', '{"Connection","Heart"}', '{"boundaries"}', '{"gratitude","compassion"}', '{"giving","open-handedness"}'),
  ('gentleness', 'Gentleness', 'Water', 'Strength that doesn''t need to be hard.', 'Gentleness is a river smoothing stone: soft, unhurried, and still changing everything it touches. It''s a calm voice in a tense moment, a careful hand, words chosen so they can be heard. Gentleness isn''t weakness; it takes real strength to stay soft when it would be easier to harden.', 'Too much, and gentleness can become avoidance. You might soften every truth until it disappears, or let others walk over you rather than risk seeming harsh. Not every moment needs a soft touch; some need a firm one.', 'Without gentleness, life gets sharp-edged. You may be hard on yourself in ways you''d never be with a friend, or brace against the world as if softness would cost you. Harshness often began as protection.', '{"Heart","Connection"}', '{"honesty"}', '{"patience","compassion"}', '{"softness","mildness"}'),
  ('healing', 'Healing', 'Water', 'Tending old wounds so they can close.', 'Healing is a wound knitting closed, slowly, from the inside out. It''s giving pain the care and time it needs, rather than pretending it isn''t there. Healing can look like therapy, rest, a long walk, a good cry, or finally being kind to the part of you that got hurt.', 'Too much, and healing can become an identity. Life turns into one long project of fixing yourself, as if you can''t live fully until every wound is gone. Sometimes the healing you need is permission to live well alongside a scar.', 'Without healing, old hurts keep speaking through new moments. You may react strongly to small things, or steer around anything that reminds you of the past. Unhealed pain isn''t a failing; it''s something that hasn''t yet had what it needed.', '{"Heart","Body"}', '{"joy"}', '{"rest","compassion"}', '{"mending","convalescence"}'),
  ('hope', 'Hope', 'Water', 'Leaning toward what could still be good.', 'Hope is a seed in winter ground: nothing to see yet, but something alive. It''s the quiet belief that things can change, and that you have a part in changing them. Hope in practice is small and stubborn: making a plan, planting something, getting up and trying again.', 'Too much, and hope can float free of what''s real. It can keep you waiting for someone to change, or for things to fix themselves, while life passes by. Hope without action can become a gentle way of not deciding.', 'Without hope, the future flattens. Effort can feel pointless, and you may stop reaching for anything in case it doesn''t come. Hopelessness is often deep exhaustion speaking. It deserves care, and sometimes the support of others.', '{"Heart","Spirit"}', '{"acceptance"}', '{"trust","courage"}', '{"optimism","expectancy"}'),
  ('intimacy', 'Intimacy', 'Water', 'Letting someone truly close.', 'Intimacy is two candles leaning close, each flame brighter for the other. It''s being known, and knowing someone, beneath the surface: the fears, the hopes, the odd little habits. Intimacy lives in honest conversations, comfortable silences, touch that feels safe, and the slow trust of being loved as you are.', 'Too much, and intimacy can blur into merging, where you lose track of where you end and the other begins. It can become dependence, or the expectation that one person meet every need. Closeness without breathing room starts to suffocate.', 'Without intimacy, even a full life can feel lonely. You might keep people at a polite distance, share facts but not feelings, or feel unseen in your closest relationships. Often the walls went up for good reasons; they can come down slowly.', '{"Connection","Heart"}', '{"boundaries"}', '{"vulnerability","trust"}', '{"closeness","nearness"}'),
  ('intuition', 'Intuition', 'Water', 'The quiet voice beneath the noise that already knows.', 'Intuition is knowing that arrives before the reasons do, like a compass needle settling before you''ve read the map. It speaks through the body, a tightening or an easing, and through images, dreams and hunches. Put simply, it is your whole self noticing patterns faster than your thinking mind can explain. Listening to it can bring you home to yourself.', 'Followed without question, intuition can mistake fear for foresight or a wish for a sign. You might read meaning into everything, or dismiss facts that don''t fit the feeling. Not every whisper is wisdom.', 'When intuition is ignored, life can feel like following other people''s maps. You may second-guess every choice and look outside yourself for permission. That inner voice often went quiet because it wasn''t welcome once. It returns when it''s listened to.', '{"Heart","Spirit"}', '{"clarity"}', '{"trust","presence"}', '{"instinct","inner voice"}'),
  ('joy', 'Joy', 'Water', 'Letting gladness in, without waiting for a reason.', 'Joy is sunlight on water: it doesn''t ask permission, it just arrives and shimmers. It''s the lift of a good song, a friend''s laugh, the first warm day of spring. Joy isn''t the same as being happy all the time. In practice, it''s letting yourself fully feel the good when it comes, instead of bracing for what might go wrong next.', 'Too much, and joy can become a performance: always bright, always fine, with no room for the harder feelings. Chasing the next high can leave you skimming the surface of your own life, or quietly telling others their sadness isn''t welcome.', 'Without joy, days go grey and dutiful. You may notice yourself holding back from delight, as if happiness has to be earned or will be taken away. Sometimes the absence of joy is grief or exhaustion, asking to be tended first.', '{"Heart","Play"}', '{"acceptance"}', '{"gratitude","presence"}', '{"happiness","elation"}'),
  ('kindness', 'Kindness', 'Water', 'Small, everyday warmth.', 'Kindness is a lamp left on in the window for someone coming home late. It''s the small, everyday acts that make life gentler: holding a door, remembering a name, a kind word at the right moment. Kindness asks nothing in return. It simply makes the world a little warmer, one moment at a time.', 'Too much, and kindness can turn into niceness: smiling through things that need saying, saying yes when you mean no. Kindness that avoids every hard truth can leave people without what they really need to hear.', 'Without kindness, the world feels colder and more transactional. You might notice yourself becoming impatient, harsh, or simply too busy to see others. Unkindness often grows where kindness has been missing for a long time, including toward yourself.', '{"Connection","Heart"}', '{"honesty"}', '{"compassion","empathy"}', '{"goodness","considerateness"}'),
  ('nurturing', 'Nurturing', 'Water', 'Helping someone, or something, grow.', 'Nurturing is a gardener''s hands in the soil: patient, attentive, and glad when green appears. It''s feeding, encouraging and sheltering what''s young or fragile, whether that''s a child, a friend, a project, or a part of yourself. Good nurture gives what''s needed, then steps back to let growth happen.', 'Too much, and nurturing turns into smothering. Care becomes control, help becomes hovering, and others never get the chance to grow strong on their own. Sometimes over-nurturing is a quiet way of feeling needed.', 'Without nurture, things wither, in others and in you. You might give endlessly to others while leaving yourself unfed, or find it hard to receive care at all. Many of the greatest nurturers were never nurtured enough themselves.', '{"Connection","Heart"}', '{"freedom"}', '{"compassion","patience"}', '{"fostering","cherishing"}'),
  ('peace', 'Peace', 'Water', 'A settled heart, even when life is loud.', 'Peace is the still water deep in a lake while wind ruffles the surface. It isn''t the absence of trouble; it''s a steadiness underneath it. In everyday life, peace looks like responding instead of reacting, choosing calm where you can, and helping the people around you feel safe enough to settle too.', 'Too much, and peace becomes peace at any price. Keeping things calm can mean swallowing what needs saying, avoiding a conflict that would lead somewhere better, or numbing out rather than feeling. A quiet room isn''t always a peaceful one.', 'Without peace, the mind rarely rests. Everything feels urgent and small things land like big ones. You may find yourself bracing even in safe moments, a sign your body learned long ago that calm couldn''t be trusted.', '{"Heart","Spirit"}', '{"courage"}', '{"acceptance","presence"}', '{"serenity","tranquillity"}'),
  ('rest', 'Rest', 'Water', 'The sacred art of doing nothing, fully.', 'Rest is the field lying fallow so it can grow again. It''s letting yourself be restored without needing to earn it first. In everyday terms: sleep, stillness, a slow walk, an afternoon with no plans, anything that truly refills you rather than just filling time. From rest, the rest of life becomes possible again.', 'Too much, and rest can become a place to hide. Stillness slides into avoidance, recovery into numbing, and the things that would bring you alive keep getting postponed. Some tiredness asks for rest; some asks for change.', 'When rest is missing, everything gets thinner: patience, joy, attention, health. You may feel you have to justify every pause. Running on empty is often a story about worth, the belief that you''re only allowed to stop once everything is done.', '{"Body"}', '{"discipline"}', '{"acceptance","presence"}', '{"restoration","stillness","repose"}'),
  ('sensitivity', 'Sensitivity', 'Water', 'Feeling deeply, and honouring it as a strength.', 'Sensitivity is a finely tuned instrument: it catches notes others miss. It''s noticing the shift in a room, the beauty in small things, what''s left unsaid. At its best, sensitivity makes you a gentle friend, a careful maker, and a wise reader of people and moments.', 'Too much, and sensitivity can leave you overwhelmed: taking everything personally, or carrying feelings that aren''t yours. Without care, the instrument goes out of tune, until every sound is too loud and every mood feels like your responsibility.', 'When sensitivity is pushed down, perhaps after being called "too sensitive" too often, you may grow a hard shell. You might feel less, notice less, or feel quietly cut off from your own depth. That shell was protection; it doesn''t have to be permanent.', '{"Heart"}', '{"boundaries"}', '{"rest","empathy"}', '{"responsiveness","perceptiveness"}'),
  ('sensuality', 'Sensuality', 'Water', 'Living fully through the senses.', 'Sensuality is the first bite of ripe fruit, sun on bare skin, the smell of rain after heat. It''s being at home in your body and letting it enjoy the world: taste, touch, scent, sound and sight. Sensuality brings you out of your head and into the living moment, where pleasure is simple and honest.', 'Too much, and sensuality can tip into chasing sensation: always needing more, richer, stronger, until ordinary moments stop being enough. Pleasure can also become a way of avoiding what''s harder to feel.', 'Without sensuality, life can feel lived from the neck up. You might rush meals, ignore your body until it hurts, or feel guilty about simple pleasures. Many of us were taught that enjoying our bodies was something to be wary of.', '{"Body","Heart"}', '{"discipline"}', '{"presence","health"}', '{"earthiness","sensory pleasure"}'),
  ('vulnerability', 'Vulnerability', 'Water', 'The strength to be seen, fully and honestly.', 'Vulnerability is the flower opening its petals to the morning, not knowing what the day will bring. It''s letting the real you be met: the uncertain parts, the tender parts, the parts still growing. Plainly: allowing yourself to be seen as you are, and saying "this matters to me" without armour. It opens a door to closeness that can''t be earned any other way.', 'In excess, openness stops choosing its moment or its people. You may share more than a relationship can yet hold, or reach for being seen as a way to be rescued. Exposure without care can leave you feeling raw rather than met.', 'Without it, life gets well defended and a little lonely. You might be admired but not known. Closing off usually began as protection, and it was probably wise at the time. The ache of not being seen can be the first sign that it''s safe to open again, slowly.', '{"Heart"}', '{"wisdom"}', '{"trust","courage"}', '{"openness of heart","emotional exposure"}'),
  ('achievement', 'Achievement', 'Fire', 'The quiet pride of a thing done well.', 'Achievement is reaching the summit and looking back at the path you climbed. It''s setting a goal, working toward it, and letting yourself feel the satisfaction of reaching it. Achievement builds trust in yourself: proof that what you set out to do, you can do.', 'Too much, and achievement becomes a treadmill. Every goal reached just raises the next bar, and your worth starts to depend on what you produce. Achievement without rest or meaning can leave you accomplished and empty.', 'Without achievement, effort may feel scattered or unrewarded. You might downplay what you do, or stop setting goals in case you fail. Sometimes the missing piece is simply noticing how much you already achieve.', '{"Purpose"}', '{"rest"}', '{"discipline","determination"}', '{"accomplishment","attainment"}'),
  ('ambition', 'Ambition', 'Fire', 'Reaching toward the peak you can see from where you stand.', 'Ambition is the part of you that looks at the mountain and wants to climb it. It gives direction to effort and shape to dreams. Plainly put: a desire to grow, achieve or contribute beyond where you are now, and the willingness to work for it. Healthy ambition says "I can become more," not "I am not enough."', 'Too much, and every summit only reveals a higher one. Worth becomes tied to achievement, and rest feels like falling behind. You might climb past the people you love without noticing.', 'Without ambition, life may drift in comfortable circles. You might hold back from goals for fear of failure, or of being seen to want. Often ambition is quiet rather than absent, waiting for permission to want something openly.', '{"Purpose"}', '{"gratitude"}', '{"discipline","meaning"}', '{"aspiration","striving"}'),
  ('assertiveness', 'Assertiveness', 'Fire', 'Asking clearly for what you need.', 'Assertiveness is a clear bell: it rings true without shouting. It''s stating your needs, views and limits directly and respectfully, trusting they matter as much as anyone''s. Assertiveness lets people know where they stand with you, which makes trust easier.', 'Too much, and assertiveness slides into aggression or bulldozing. You may push your needs over others'', or confuse winning with being heard. Clear isn''t the same as forceful.', 'Without assertiveness, needs go unspoken and resentment quietly builds. You might hint instead of ask, agree instead of say what you think, or hope others will just know. Many sensitive people were taught that asking was selfish. It isn''t.', '{"Connection","Purpose"}', '{"empathy"}', '{"boundaries","honesty"}', '{"directness","self-advocacy"}'),
  ('boldness', 'Boldness', 'Fire', 'Taking up the room you need.', 'Boldness is a bright flag in the wind, unashamed of being seen. It''s dreaming big, speaking up, wearing the colour, asking for more. Bold people give others permission to be fully themselves too.', 'Too much, and boldness can become recklessness or showing off. You may take risks that hurt you or others, or fill every room so no one else has space. Boldness without care can trample.', 'Without boldness, you might play small to stay safe, dimming yourself so you don''t draw attention. Many of us learned to shrink to fit in. Taking up space can be relearned.', '{"Spirit","Play"}', '{"wisdom"}', '{"courage","confidence"}', '{"audacity","fearlessness"}'),
  ('celebration', 'Celebration', 'Fire', 'Marking the good moments on purpose.', 'Celebration is lanterns strung across a summer night. It''s pausing to mark what matters: wins, milestones, love, survival. Celebration turns ordinary days into memories, and reminds us that life is worth gathering for.', 'Too much, and celebration can become constant distraction, a party that never ends so nothing ever has to be felt. It can also turn into excess that leaves you depleted rather than lifted.', 'Without celebration, achievements slip by unnoticed and life starts to feel like one long to-do list. You might feel uncomfortable being celebrated, or wait for a big enough reason that never comes.', '{"Play","Connection"}', '{"rest"}', '{"joy","gratitude"}', '{"festivity","rejoicing"}'),
  ('confidence', 'Confidence', 'Fire', 'Trusting you can meet what comes.', 'Confidence is a lantern held steady in a dark lane: it doesn''t light the whole road, just enough for the next step. It''s trusting your own ability to learn, try and recover. Confident people aren''t sure of everything; they''re simply willing to show up without needing a guarantee.', 'Too much, and confidence hardens into certainty. You may stop listening, brush past other views, or mistake loudness for strength. Overconfidence can also be armour, covering doubts that never get a chance to be heard.', 'Without confidence, you might second-guess every choice, wait for permission, or shrink in rooms where you belong. Low confidence is rarely about ability. More often it''s an old voice that once told you that you weren''t enough.', '{"Spirit","Purpose"}', '{"openness"}', '{"courage","resilience"}', '{"self-assurance","poise"}'),
  ('courage', 'Courage', 'Fire', 'The willingness to act in the presence of fear.', 'Courage is the small flame that keeps walking into the wind. It isn''t the absence of fear; it''s moving with it. Plainly: acting on what matters even when you''re afraid, speaking the true thing, beginning the uncertain thing, staying in the hard conversation. Most courage is quiet: getting up again, asking for what you need, choosing what feels more alive than safe.', 'Unchecked, courage can become recklessness, or a need to prove something. Risk becomes the point rather than the path. You might override signals from your body or the people around you, mistaking constant intensity for strength.', 'When courage is missing, life narrows around what feels safe. Wishes wait for a better time. The fear usually has a history and deserves respect. And yet the life that''s calling you tends to sit just past the edge of that fear.', '{"Spirit"}', '{"wisdom"}', '{"vulnerability","trust"}', '{"bravery","daring","nerve"}'),
  ('creativity', 'Creativity', 'Fire', 'Making something from nothing, again and again.', 'Creativity is the spark that leaps from your inner world into form. It''s the part of you that plays with what could be. Literally: making something new, a song, a meal, a garden, a fresh way through an old problem, from the raw materials of your life. Creating reminds you the world is still being made, and that you''re one of its makers.', 'Too much, and creativity can scatter into endless beginnings that never finish. Or your worth can become fused with what you make, so every piece becomes a verdict. The muse turns into a harsh critic.', 'When creativity goes quiet, life can feel flat and borrowed. Often it''s been shamed out, or crowded out, rather than lost. The longing to make something is the part of you that hasn''t forgotten.', '{"Play"}', '{"discipline"}', '{"playfulness","freedom"}', '{"imagination","inventiveness","making"}'),
  ('desire', 'Desire', 'Fire', 'Knowing what you want, and letting yourself want it.', 'Desire is the pull of the moon on the tide, a quiet force that moves you. It''s knowing what you long for, in love, work, pleasure and life, and allowing that wanting without shame. Desire points toward what makes you feel alive.', 'Too much, and desire can drive you rather than guide you. Wanting can become grasping, or a chase that''s never satisfied. Desire can also lead you toward what feels good now but costs you later.', 'Without desire, life can feel flat and directionless. You might not know what you want, or feel you''re not allowed to want much at all. For many people, desire was something to hide. Rediscovering it is a homecoming.', '{"Heart","Play"}', '{"discipline"}', '{"passion","authenticity"}', '{"longing","wanting"}'),
  ('determination', 'Determination', 'Fire', 'Keeping going when it''s hard.', 'Determination is water wearing a path through rock: not forceful, just unwilling to stop. It''s the quiet decision to keep going after the excitement fades and the obstacles arrive. Determination turns hopes into results, one stubborn day at a time.', 'Too much, and determination becomes rigidity. You may push on long after something stopped serving you, ignore the body''s warnings, or treat quitting as failure even when it''s wisdom. Not every wall is meant to be broken through.', 'Without determination, plans fade at the first setback. You might start many things and finish few, or give up just before the turning point. Sometimes the missing piece isn''t willpower but a reason that matters enough.', '{"Purpose"}', '{"adaptability"}', '{"discipline","hope"}', '{"resolve","grit"}'),
  ('discipline', 'Discipline', 'Fire', 'The practice of choosing yourself, every day.', 'Discipline is the steady drip of water that, day by day, shapes stone. It''s keeping small promises to yourself until they become who you are. In plain terms: doing what you''ve chosen to do, consistently, even when motivation dips. It isn''t punishment. It''s devotion in repeated form, giving what you care about time, attention and the chance to grow.', 'Too much, and discipline hardens into rigidity or self-punishment. Rules replace listening, and missing a day feels like failing as a person. The practice can quietly become a way to control fear rather than to serve life.', 'Without discipline, intentions stay intentions. You might feel scattered, pulled by every urge, and quietly disappointed in yourself. That absence isn''t a character flaw. It often means the goal isn''t truly yours, or the structure around it hasn''t been kind enough.', '{"Body","Purpose"}', '{"rest"}', '{"commitment","patience"}', '{"self-mastery","dedication","rigour"}'),
  ('freedom', 'Freedom', 'Fire', 'The open sky inside you, where you choose your own direction.', 'Freedom is the felt sense that your life belongs to you. Like a bird that knows the sky is open, it isn''t about always flying, but knowing you could. In plain terms: the ability to make your own choices, move your own way, and say yes or no from the inside. Freedom lets you shape a life, not just fill one.', 'Too much, and freedom becomes an allergy to anything that holds you. Every commitment feels like a cage, so you keep one foot out the door. The bird that never lands never builds a nest.', 'Without freedom, life can feel lived on someone else''s terms. You might follow rules you never chose and swallow wants you never voiced. The restlessness you feel is a signal, not a flaw: something in you wants room to breathe.', '{"Play","Spirit"}', '{"commitment"}', '{"courage","authenticity"}', '{"liberty","independence of spirit"}'),
  ('initiative', 'Initiative', 'Fire', 'Starting, without waiting to be asked.', 'Initiative is the first spark that catches the kindling. It''s noticing what needs doing and doing it, beginning before everything is perfect. People with initiative make things happen, solve small problems early, and open doors others walk past.', 'Too much, and initiative can rush ahead of others. You may start more than you can finish, act before thinking, or take over things that weren''t yours to begin. Not every gap needs filling by you.', 'Without initiative, life can become a waiting room. You might hold off until asked, until ready, until certain. Waiting for the perfect moment often means the moment never comes.', '{"Purpose"}', '{"patience"}', '{"courage","curiosity"}', '{"enterprise","proactivity"}'),
  ('leadership', 'Leadership', 'Fire', 'Going first, so others can follow.', 'Leadership is the first bird at the point of the flock, taking the wind so others can fly easier. It''s seeing where things could go and helping people get there together. Good leaders listen, decide, and carry responsibility when it''s heavy.', 'Too much, and leadership becomes the need to be in charge. You may take over when no one asked, struggle to follow, or carry everything yourself because you don''t trust others to. A leader who can''t let go grows followers, not leaders.', 'Without leadership, groups drift and good ideas go nowhere. You might hold back from stepping up, waiting for someone more qualified. Often the person who sees what''s needed is exactly the one who''s meant to begin.', '{"Purpose","Connection"}', '{"service"}', '{"integrity","courage"}', '{"guidance","captaincy"}'),
  ('passion', 'Passion', 'Fire', 'The fire that makes you forget to check the time.', 'Passion is the hearth-fire of the soul, warming everything it touches. It''s what you''d do for no reward, what lights you up when you speak of it. Literally: strong, energising care for something, a craft, a cause, a person, that pulls you toward it. Passion turns effort into devotion.', 'Too much, and the fire consumes its own fuel. Passion can become obsession, burning through sleep, relationships and health. What once warmed you starts to scorch.', 'Without passion, days can feel grey and interchangeable. You do what needs doing, but nothing catches. Often the spark isn''t gone, only buried under duty or disappointment. It tends to relight near the things you once loved.', '{"Purpose","Play"}', '{"rest"}', '{"meaning","creativity"}', '{"fervour","ardour"}'),
  ('playfulness', 'Playfulness', 'Fire', 'Letting life be a little bit of a game again.', 'Playfulness is the child in you who still believes puddles are for jumping. It''s lightness, experimentation, the joy of doing something just because it''s fun. In practical terms: approaching life, and people, with openness and enjoyment rather than constant seriousness. Play isn''t the opposite of work; it''s often what makes the work bearable, and the learning stick.', 'Too much, and play becomes a way to never land. Every serious moment gets deflected with a joke, and responsibilities are always tomorrow''s. The game continues while the real conversation waits.', 'Without play, life grows heavy and grown-up in all the wrong ways. You might feel you have to earn fun, or that silliness is beneath you. The part of you that wants to play hasn''t gone; it''s waiting to be invited.', '{"Play"}', '{"responsibility"}', '{"humour","wonder"}', '{"fun","levity"}'),
  ('power', 'Power', 'Fire', 'Owning your capacity to shape your life.', 'Power is the current in a river: it moves things. It''s knowing you have a say in your life and using it, making choices, taking up space, influencing what happens around you. Healthy power is power with others, not over them.', 'Too much, and power turns into control. It can push others down, demand to be right, or use people as stepping stones. Power without care quickly becomes something people fear rather than trust.', 'Without power, you may feel that life just happens to you. You might wait for others to decide, or believe your wants don''t count. Feeling powerless is often learned, and it can be unlearned, one choice at a time.', '{"Spirit","Purpose"}', '{"compassion"}', '{"confidence","integrity"}', '{"agency","capability"}'),
  ('resilience', 'Resilience', 'Fire', 'The ember that stays warm through the longest night.', 'Resilience is the ember beneath the ash, still glowing after the storm has passed. It isn''t about never falling, but about finding your way back up, often changed, sometimes stronger. In plain terms: the capacity to recover from difficulty, adapt, and keep going. It''s built slowly, through support, rest and each small return.', 'Too much, and resilience hardens into toughing it out alone. You might keep going long after you should have stopped, or refuse help because you "can handle it." Endurance becomes a wall around your need.', 'When resilience wears thin, every setback feels like the final one. Hope becomes hard to reach. That''s not weakness; it''s what happens when too much has been carried for too long. Rest and gentle support are what help the ember catch again.', '{"Heart","Body"}', '{"vulnerability"}', '{"acceptance","trust"}', '{"hardiness","steadiness"}'),
  ('strength', 'Strength', 'Fire', 'Power you can lean on, in body and in will.', 'Strength is an old tree in a storm: it bends, it creaks, it stays. It''s the capacity to carry what needs carrying, in your muscles and in your spirit. Strength shows up in lifting, in enduring, and in standing firm for yourself and others when it counts.', 'Too much, and strength can become hardness. You may refuse help, hide pain, or believe you always have to be the strong one. Strength that never rests eventually cracks.', 'Without strength, life can feel like too much to hold. You might feel fragile, easily knocked over, or dependent on others to carry you. Strength grows back in small, steady ways, through rest, movement and support.', '{"Body","Spirit"}', '{"gentleness"}', '{"health","resilience"}', '{"fortitude","sturdiness"}'),
  ('transformation', 'Transformation', 'Fire', 'Becoming more of who you are.', 'Transformation is the caterpillar in the chrysalis: everything dissolves so something new can form. It''s real, deep change, letting old patterns end and new ways of being grow. Transformation often begins with a crack, a loss, or a longing that won''t go away.', 'Too much, and transformation becomes constant reinvention, never settling long enough to grow roots. You may keep changing to escape, rather than to become. Not everything needs to be transformed; some things need to be kept.', 'Without transformation, you might feel stuck in a version of yourself you''ve outgrown. Life repeats itself, and the same patterns play out again and again. Change can feel frightening, especially if it once cost you a lot.', '{"Spirit"}', '{"acceptance"}', '{"courage","alchemy"}', '{"metamorphosis","reinvention"}'),
  ('boundaries', 'Boundaries', 'Earth', 'Knowing where you end and where others begin.', 'Boundaries are the garden fence that lets the garden flourish. They mark where you end and others begin. Plainly: knowing your limits with time, energy, body and feelings, and communicating them clearly. Good boundaries make real closeness possible, because people can trust your yes when you''re able to say no.', 'Too rigid, and boundaries become walls. You might keep people out before they can hurt you, or use rules to avoid the risk of real contact. Protection can quietly turn into isolation.', 'Without boundaries, you may say yes when you mean no, and resentment builds up in the gaps. You end up living other people''s priorities. The exhaustion is information: a part of you asking to be protected.', '{"Connection"}', '{"openness"}', '{"integrity","compassion"}', '{"limits","self-protection"}'),
  ('commitment', 'Commitment', 'Earth', 'Choosing to stay, and meaning it.', 'Commitment is putting down roots and letting them grow deep. It''s the promise that holds on the ordinary days, not just the easy ones. In practical terms: dedicating yourself to a person, a path or a practice over time, and following through even when enthusiasm fades. Depth only comes to what we stay with.', 'Too much, and commitment keeps you rooted in soil that no longer nourishes you. You might stay out of duty, fear or pride, long after something has ended. Loyalty becomes a way of not listening to yourself.', 'Without commitment, life can feel like a string of beginnings. Nothing gets old enough to become deep. Hesitating to commit is often protection against loss. Starting small, with one chosen promise, can make staying feel safe.', '{"Connection","Purpose"}', '{"freedom"}', '{"integrity","patience"}', '{"dedication","steadfastness"}'),
  ('community', 'Community', 'Earth', 'Being part of something together.', 'Community is a village where everyone knows your name and someone always has a spare cup of sugar. It''s belonging to a group that shares life: neighbours, friends, teams, circles. Community means giving and receiving support, celebrating together, and never having to do everything alone.', 'Too much, and community can pressure people to conform, or close itself off from outsiders. You may lose your own voice to fit the group, or feel you can never step away.', 'Without community, life can feel isolated. You may carry everything alone, struggle to find support in hard times, or feel invisible. Many people long for community but don''t know where to begin.', '{"Connection"}', '{"freedom"}', '{"kindness","service"}', '{"fellowship","togetherness"}'),
  ('diligence', 'Diligence', 'Earth', 'Careful, steady effort.', 'Diligence is a stonemason fitting each stone with care, knowing the wall depends on it. It''s doing your work thoroughly and well, even when no one is watching. Diligence builds quality, trust and quiet pride.', 'Too much, and diligence becomes perfectionism or overwork. You may struggle to finish because nothing is good enough, or work long past what''s healthy. Diligence can turn into a way of earning worth.', 'Without diligence, work can feel rushed, careless or half-done. You might cut corners, then feel uneasy about the results. Sometimes a lack of diligence is exhaustion, or work that has lost its meaning.', '{"Purpose"}', '{"rest"}', '{"discipline","patience"}', '{"conscientiousness","industriousness"}'),
  ('family', 'Family', 'Earth', 'The people who knew you before you knew yourself.', 'Family is the root system beneath the forest floor, quietly connecting and nourishing. By blood or by choice, it''s where belonging takes root. Plainly: the people who hold your history, show up in the ordinary and the hard hours, and let you be known across the years. Tending family is tending your roots.', 'In excess, family can become enmeshment or obligation. Loyalty to the group may cost you your own voice, and old roles keep you smaller than you''ve become. Love and duty get tangled.', 'When family feels absent or painful, there can be a lasting ache for home. That longing is real and worth honouring. Many people find, or build, the family they need, and it counts just as much.', '{"Connection"}', '{"boundaries"}', '{"love","forgiveness"}', '{"kin","belonging","home"}'),
  ('groundedness', 'Groundedness', 'Earth', 'Feet on the earth, here and now.', 'Groundedness is roots reaching deep into the soil, holding steady whatever the weather. It''s being in your body and in the present, connected to what''s real. Grounded people can stay calm in a storm, think clearly under pressure, and help others steady too.', 'Too much, and groundedness can become heaviness. You may dismiss dreams as unrealistic, resist imagination, or become so practical that wonder can''t get in.', 'Without groundedness, you may feel scattered, anxious or carried away by every thought and feeling. Life can feel like it''s happening in your head. The body is always here, ready to bring you back.', '{"Body","Spirit"}', '{"wonder"}', '{"presence","health"}', '{"rootedness","centredness"}'),
  ('health', 'Health', 'Earth', 'Tending the body that carries you through every day of your life.', 'Health is the soil in which the rest of life grows. When it''s cared for, energy, mood and clarity have something to root into. Literally: looking after your body and mind through food, movement, sleep and care, as an act of respect rather than punishment. Health isn''t a finish line; it''s an ongoing friendship with the body you live in.', 'Too much, and health becomes a project of control. Every meal is a test, every rest day a failure, and the body an enemy to be managed. The pursuit of wellness can quietly make you unwell.', 'When health is neglected, the body starts to speak louder: tiredness, aches, low mood. Often this isn''t laziness but overwhelm, or a long habit of putting yourself last. Small acts of care are often the kindest place to start.', '{"Body"}', '{"acceptance"}', '{"discipline","rest"}', '{"wellbeing","vitality of body"}'),
  ('hospitality', 'Hospitality', 'Earth', 'Making others feel welcome.', 'Hospitality is a kettle on and the door left open. It''s welcoming people into your home, your table, your life, and helping them feel at ease. Hospitality turns strangers into friends and houses into homes.', 'Too much, and hospitality can leave you drained, always hosting and never resting. You may feel responsible for everyone''s comfort, or struggle to close the door when you need space.', 'Without hospitality, life can feel closed off. You might hesitate to invite people over, feeling your home or yourself isn''t good enough. Welcome doesn''t need perfection, just warmth.', '{"Connection","Home & Earth"}', '{"boundaries"}', '{"generosity","comfort"}', '{"welcome","warm-heartedness"}'),
  ('integrity', 'Integrity', 'Earth', 'Being the same person in every room.', 'Integrity is a tree whose roots and branches grow from the same seed. What you believe, say and do all point the same way. In plain terms: living by your values consistently, whether or not anyone is watching. It lets others trust you and lets you trust yourself, and there''s a deep ease in having nothing to keep track of.', 'Taken too far, integrity can stiffen into self-righteousness or perfectionism. Every lapse, in yourself or others, becomes a betrayal. The desire to be good can crowd out the humility to be human.', 'When integrity slips, life splits into versions. You manage appearances, and a quiet unease follows you. Usually this starts small, with a compromise made to belong or to stay safe. Noticing the split is the beginning of mending it.', '{"Purpose"}', '{"forgiveness"}', '{"honesty","courage"}', '{"wholeness","honour","alignment"}'),
  ('patience', 'Patience', 'Earth', 'Trusting the seed while it''s still underground.', 'Patience is the farmer''s faith: you plant, you tend, and you let the season do its work. It knows that good things often grow slowly and out of sight. In practical terms: staying calm and kind while waiting, whether for results, for people, or for yourself to change. Patience turns time into an ally.', 'Too much, and patience becomes endless waiting. You might tolerate what should be challenged, or stay in situations that never change. The seed you wait for may not be in the ground at all.', 'Without patience, everything feels urgent and every delay like failure. You might pull up the seedlings to check whether they''re growing. Impatience often hides fear, that if it doesn''t happen now, it never will.', '{"Heart"}', '{"courage"}', '{"acceptance","trust"}', '{"forbearance","calm"}'),
  ('prosperity', 'Prosperity', 'Earth', 'Enough, and the means to share it.', 'Prosperity is a harvest barn filled before winter. It''s having the resources you need to live well, care for those you love, and give to others. Healthy prosperity means security, freedom and the ability to choose, not just accumulation.', 'Too much, and prosperity can become greed or endless accumulation. Money can turn into a measure of worth, and enough is never enough. Wealth without purpose can isolate.', 'Without prosperity, life can feel constrained and anxious. Money worries may shape every decision. Many people carry beliefs about money from childhood that quietly keep them in lack.', '{"Home & Earth","Purpose"}', '{"generosity"}', '{"diligence","stewardship"}', '{"wealth","thriving"}'),
  ('respect', 'Respect', 'Earth', 'Treating people, and yourself, as worthy.', 'Respect is giving a tree room to grow its own shape. It''s treating others as whole people with their own minds, choices and dignity, and expecting the same for yourself. Respect shows in listening, keeping your word, honouring differences, and not taking people for granted.', 'Too much, and respect can turn into deference: putting others on pedestals, never questioning authority, or swallowing your view out of politeness. Respect for others shouldn''t cost you respect for yourself.', 'Without respect, relationships wear thin. You may feel dismissed or overlooked, or notice yourself dismissing others. A lack of self-respect often shows up as accepting less than you deserve.', '{"Connection"}', '{"assertiveness"}', '{"fairness","kindness"}', '{"regard","esteem"}'),
  ('responsibility', 'Responsibility', 'Earth', 'Tending what''s been placed in your hands.', 'Responsibility is the gardener''s steady attention: watering, weeding, showing up for what depends on you. It''s being someone others can count on, and owning your part when things go wrong. Plainly: keeping your commitments, caring for what''s yours to care for, and answering for your choices. There is quiet dignity in being dependable.', 'Too much, and you start tending gardens that were never yours. Over-responsibility carries everyone''s feelings and outcomes, leaving no room to be carried yourself. Care curdles into control, or exhaustion.', 'Without responsibility, life can feel unmoored, as if things just happen to you. Promises slip and trust thins. Sometimes this grows from having carried too much too young. Taking back small, chosen responsibilities can rebuild the ground.', '{"Purpose","Home & Earth"}', '{"trust"}', '{"integrity","commitment"}', '{"dependability","reliability of care"}'),
  ('security', 'Security', 'Earth', 'Safe footing for you and yours.', 'Security is a well-built home with a strong roof before the rains. It''s knowing you and the people you love are safe: physically, financially and emotionally. Security lets the nervous system rest, and gives you the confidence to take healthy risks.', 'Too much, and security can become fear-driven control. You may never take risks, hoard resources, or stay in situations that feel safe but limit you. Life can''t be made entirely safe, and trying can shrink it.', 'Without security, life feels precarious. You may live in survival mode, always bracing for the next crisis. Feeling unsafe for a long time can shape how you see everything.', '{"Home & Earth"}', '{"courage"}', '{"stability","responsibility"}', '{"safety","protection"}'),
  ('self-care', 'Self-care', 'Earth', 'Tending yourself as you''d tend someone you love.', 'Self-care is watering your own garden, not just your neighbours''. It''s paying attention to what you need, physically, emotionally and mentally, and meeting those needs with kindness. Real self-care is often simple: sleep, food, movement, boundaries, rest, and time that''s just yours.', 'Too much, and self-care can become self-indulgence or avoidance. Bubble baths can''t fix what needs a hard conversation. Self-care can also become another task on the list, done perfectly and without joy.', 'Without self-care, you run on empty. You may notice exhaustion, irritability, illness or numbness. Many caregivers put themselves last for so long they forget they matter too.', '{"Body","Heart"}', '{"service"}', '{"rest","health"}', '{"self-nurture","self-tending"}'),
  ('service', 'Service', 'Earth', 'Useful, humble help.', 'Service is a bridge built for others to cross. It''s using your skills, time and energy to make life better for others, without needing the spotlight. Service can be a career, a volunteer shift, or simply being the person who shows up when help is needed.', 'Too much, and service becomes self-sacrifice. You may give until you''re empty, feel guilty saying no, or tie your worth to how useful you are. Service that ignores your own needs eventually runs dry.', 'Without service, life can feel self-focused and less meaningful. You may feel disconnected from something bigger than yourself. Helping others is one of the surest paths back to purpose.', '{"Connection","Purpose"}', '{"self-care"}', '{"kindness","community"}', '{"helpfulness","volunteering"}'),
  ('stability', 'Stability', 'Earth', 'Steady ground to build a life on.', 'Stability is bedrock beneath the soil: unseen, unshaken, holding everything up. It''s having routines, relationships and foundations you can rely on. Stability gives you a steady base from which to grow, explore and recover.', 'Too much, and stability turns into rigidity. You may resist all change, cling to routines that no longer serve you, or stay somewhere long after it''s time to go. Stable can become stuck.', 'Without stability, life feels shaky and unpredictable. You might move from crisis to crisis, struggle to rest, or feel unable to plan ahead. Building stability often starts small: one steady habit, one reliable person.', '{"Home & Earth","Body"}', '{"adaptability"}', '{"discipline","security"}', '{"constancy","firm footing"}'),
  ('stewardship', 'Stewardship', 'Earth', 'Caring for home and earth as if they were lent to you.', 'Stewardship is the heart of a guardian: tending your home, your resources and the living world as gifts to pass on. Like someone who plants trees whose shade they may never sit in, it looks beyond the moment. Plainly: using and caring for what you have, money, space, nature, with respect and a thought for those who come after.', 'Too much, and stewardship can become anxious control, or a crushing sense that the whole world''s fate rests on your choices. Care turns into guilt, and guilt into paralysis.', 'Without stewardship, things drift: a home that feels temporary, resources that slip away, a sense of disconnection from the land. Often it''s not carelessness but overwhelm. Tending one small patch well is a real beginning.', '{"Home & Earth"}', '{"acceptance"}', '{"responsibility","gratitude"}', '{"guardianship","care of place"}'),
  ('sustainability', 'Sustainability', 'Earth', 'Living so the earth can keep giving.', 'Sustainability is planting trees whose shade you may never sit in. It''s living in a way the earth, and the people who come after us, can keep living with. Sustainability shows in choices about what we buy, waste, eat, travel and protect.', 'Too much, and sustainability can become eco-guilt or judgement: feeling that nothing is ever enough, or looking down on others'' choices. Burnout helps no one, including the planet.', 'Without sustainability, the future feels far away and consumption easy. You may feel helpless about the scale of the problem, so nothing changes. Small actions matter, especially when shared.', '{"Home & Earth"}', '{"prosperity"}', '{"stewardship","responsibility"}', '{"conservation","eco-living"}'),
  ('tradition', 'Tradition', 'Earth', 'Carrying forward what deserves to last.', 'Tradition is a recipe passed down through generations, each hand adding a little something. It''s the customs, stories and practices that connect you to those who came before. Tradition gives belonging, meaning and a sense of being part of something larger than yourself.', 'Too much, and tradition becomes "we''ve always done it this way". It can resist needed change, exclude those who don''t fit, or carry old harms forward unquestioned.', 'Without tradition, life can feel rootless and unanchored. Holidays may pass unmarked; family stories go untold. Sometimes traditions were lost through migration, conflict or pain, and new ones can be created.', '{"Connection","Home & Earth"}', '{"openness"}', '{"family","gratitude"}', '{"heritage","custom"}'),
  ('advocacy', 'Advocacy', 'Air', 'Speaking up for what, and who, matters.', 'Advocacy is a voice raised for someone who can''t be heard. It''s standing up for people, causes and values that matter, using your voice, skills and influence to make things fairer. Advocates turn caring into change.', 'Too much, and advocacy can become self-righteousness, or speaking over the very people you mean to help. You may burn out fighting every battle, or see the world only through causes.', 'Without advocacy, injustice goes unchallenged. You may stay silent when something is wrong, afraid of conflict or unsure your voice matters. Every voice adds up.', '{"Connection","Purpose"}', '{"empathy"}', '{"courage","fairness"}', '{"championing","standing up"}'),
  ('clarity', 'Clarity', 'Air', 'When the fog lifts and you can see the path.', 'Clarity is a still pond reflecting the sky. When the water settles, you can see all the way to the bottom. In plain terms: understanding what you think, feel and want, and being able to express it simply. Clarity makes decisions lighter and conversations cleaner.', 'Too much, and clarity can harden into false certainty. Everything becomes black and white, and nuance gets lost. Seeing clearly isn''t the same as seeing everything.', 'Without clarity, life can feel foggy and overwhelming. You might circle the same decisions, unsure what you want. Confusion often means too many voices, or too little quiet. Stillness tends to let the water settle.', '{"Mind"}', '{"openness"}', '{"honesty","presence"}', '{"lucidity","clear sight"}'),
  ('communication', 'Communication', 'Air', 'The art of being truly heard and truly listening.', 'Communication is a bridge built plank by plank between two inner worlds. At its best it''s honest and kind at once. In plain terms: saying what''s real, listening for what''s underneath, and repairing when words go wrong. Good communication makes people feel less alone.', 'In excess, communication can become a need to be heard at all costs: over-explaining, filling every silence, winning rather than understanding. Words multiply while connection thins.', 'When it goes missing, things are felt but not said, and distance grows in the gaps. Silence can be a habit learned in homes where speaking up wasn''t safe. The unspoken is often what most needs air.', '{"Connection"}', '{"presence"}', '{"honesty","empathy"}', '{"expression","dialogue","listening"}'),
  ('curiosity', 'Curiosity', 'Air', 'The aliveness of not-knowing, and leaning in.', 'Curiosity is the lantern held up to every unexplored path. It asks why, and what if, and tell me more. Plainly: a genuine interest in learning, exploring and understanding, whether that''s people, ideas or the world around you. It turns strangers into stories and problems into puzzles, and keeps a mind growing long after it could have stopped.', 'Too much, and curiosity scatters: always the next thing, never staying long enough to go deep. It can also cross into intrusion, wanting to know more than someone wants to share.', 'Without curiosity, life can settle into certainty and routine that feel safe but dull. Sometimes curiosity was punished, or life got too heavy for it. It tends to return when there''s a little more room to breathe.', '{"Mind","Play"}', '{"commitment"}', '{"openness","wonder"}', '{"inquisitiveness","interest","exploration"}'),
  ('diplomacy', 'Diplomacy', 'Air', 'Bridging differences with tact.', 'Diplomacy is a bridge across a river, built from both banks. It''s handling differences with care, finding common ground, and helping people who disagree move forward together. Diplomats keep relationships whole while solving hard problems.', 'Too much, and diplomacy can become people-pleasing or avoidance: smoothing everything over so no one is uncomfortable, even when something needs to be faced. Tact can turn into evasion.', 'Without diplomacy, disagreements become battles and relationships fracture. You may say things bluntly and wonder why they land badly, or avoid conflict altogether because you don''t know how to handle it.', '{"Connection"}', '{"honesty"}', '{"empathy","patience"}', '{"tact","mediation"}'),
  ('discovery', 'Discovery', 'Air', 'The thrill of finding something new.', 'Discovery is turning a corner and finding a hidden garden. It''s the joy of learning something you didn''t know, about the world, about others, about yourself. Discovery keeps life fresh, and every day a little unknown.', 'Too much, and discovery can become restlessness, always chasing the next new thing and never going deep. You may struggle to stay with anything once the newness wears off.', 'Without discovery, life can feel predictable and small. You may stick to the same routes, foods, people and ideas. A single new experience can reopen the world.', '{"Mind","Play"}', '{"patience"}', '{"curiosity","wonder"}', '{"finding out","revelation"}'),
  ('fairness', 'Fairness', 'Air', 'A balanced scale, held with an open hand.', 'Fairness is the sense that everyone deserves a seat at the table. It notices when things are uneven and cares about making them right. Put simply: treating people justly, giving and taking in balance, and standing up when someone isn''t being treated well. Fairness is how trust grows between people and within communities.', 'Too much, and fairness becomes scorekeeping. Every kindness is tallied, every slight remembered. Relationships start to feel like ledgers rather than living things.', 'Without fairness, imbalance creeps in: in relationships where one gives and the other takes, or in systems that leave some out. You might tolerate being treated unfairly, or look away when others are. Noticing the imbalance is where repair begins.', '{"Connection","Purpose"}', '{"forgiveness"}', '{"honesty","empathy"}', '{"equity","even-handedness"}'),
  ('foresight', 'Foresight', 'Air', 'Looking ahead with care.', 'Foresight is a sailor reading the sky before the storm. It''s thinking ahead, imagining consequences, and preparing for what might come. Foresight helps you build a future you''ll be glad of, and avoid avoidable trouble.', 'Too much, and foresight becomes worry: living so far ahead that you miss the present, or planning for every disaster until life feels heavy. Not every future needs rehearsing.', 'Without foresight, life can feel like one surprise after another. You may make choices you later regret, or scramble when things go wrong. A little thinking ahead goes a long way.', '{"Mind","Purpose"}', '{"presence"}', '{"wisdom","clarity"}', '{"forethought","prudence"}'),
  ('honesty', 'Honesty', 'Air', 'Letting the truth breathe, kindly.', 'Honesty is clear air between people: nothing hidden in the haze. It''s saying what''s real, even when it''s uncomfortable, and being truthful with yourself first. Plainly: not deceiving others or yourself, and being willing to speak and hear the truth. Honesty makes trust possible, and trust makes closeness possible.', 'Too much, and honesty becomes a blade. Truth delivered without care can wound, and "I''m just being honest" can excuse cruelty. Not every thought needs to be spoken, and not every moment is the right one.', 'Without honesty, small untruths gather like fog. You might tell people what they want to hear, or avoid facing what you know inside. Dishonesty usually starts as protection. Speaking one small truth can clear more air than you''d expect.', '{"Connection","Mind"}', '{"compassion"}', '{"courage","integrity"}', '{"sincerity","truthfulness of word"}'),
  ('humour', 'Humour', 'Air', 'The breeze that lifts the weight, even for a moment.', 'Humour is a window thrown open in a stuffy room. It lets in air, perspective and connection. Plainly: the ability to see and share what''s funny, including in yourself and in hard times. Laughter can be medicine for the spirit and a bridge between people.', 'Too much, and humour becomes a shield. Every tender moment gets a joke, every hard feeling a punchline. People laugh with you, but they rarely get close.', 'Without humour, life can feel heavy and too serious to breathe. You might take every mistake to heart. Humour often goes quiet in hard seasons, and that''s okay. It tends to return with rest and good company.', '{"Play","Connection"}', '{"vulnerability"}', '{"playfulness","openness"}', '{"mirth","wit"}'),
  ('inclusion', 'Inclusion', 'Air', 'Making room for everyone at the table.', 'Inclusion is a table with extra chairs, always ready for one more. It''s making sure people of every background, ability, identity and story feel they belong. Inclusion means noticing who''s missing and widening the circle.', 'Too much, and inclusion can lose discernment, welcoming every voice equally, even the ones that cause harm. It can also become performative: saying the right words without making real change.', 'Without inclusion, some people are left outside, unheard and unseen. You may not notice who''s missing, or feel left out yourself. Being excluded hurts; being included can heal.', '{"Connection"}', '{"wisdom"}', '{"fairness","empathy"}', '{"inclusiveness","welcoming"}'),
  ('innovation', 'Innovation', 'Air', 'New ways of seeing and doing.', 'Innovation is a new path cut through a familiar forest. It''s finding better ways to do things, solving problems creatively, and daring to try what hasn''t been tried. Innovators see possibility where others see the usual way.', 'Too much, and innovation can chase novelty for its own sake, abandoning what works. You may get bored easily, leave things unfinished, or dismiss old wisdom too quickly.', 'Without innovation, things stay stuck in old ways even when they no longer work. You might feel you''re not a creative or inventive person. Everyone innovates when they solve a problem in a new way.', '{"Mind","Purpose"}', '{"tradition"}', '{"creativity","curiosity"}', '{"invention","ingenuity"}'),
  ('inspiration', 'Inspiration', 'Air', 'Breathing life into ideas.', 'Inspiration is a gust of wind filling a sail. It''s the sudden spark of an idea, the lift of being moved by something beautiful, and the energy to create. Inspired people inspire others: enthusiasm is contagious.', 'Too much, and inspiration can become waiting for the muse: only acting when you feel inspired, so many ideas never become real. Inspiration without action is a beautiful daydream.', 'Without inspiration, life can feel flat and uncreative. You may feel stuck or uninspired, waiting for something to move you. Inspiration often finds us when we''re already moving.', '{"Spirit","Play"}', '{"discipline"}', '{"wonder","creativity"}', '{"spark","muse"}'),
  ('learning', 'Learning', 'Air', 'Every day, a new window opening.', 'Learning is the mind stretching its wings. It''s picking up a new skill, understanding something deeper, or seeing an old thing in a new light. Literally: gaining knowledge or ability through study, practice or experience, including the lessons life brings uninvited. A learning life stays young at heart.', 'Too much, and learning can become a way of never beginning. One more course, one more book, before you feel ready to act. Knowledge piles up while life waits.', 'Without learning, the mind settles into grooves. You might feel stuck, or believe you''re "not a learner" because school once made you feel small. Learning is far bigger than school. It returns when it''s allowed to be playful and your own.', '{"Mind"}', '{"wisdom"}', '{"curiosity","patience"}', '{"growth of mind","study"}'),
  ('mentorship', 'Mentorship', 'Air', 'Passing on what you''ve learned.', 'Mentorship is an older tree sheltering saplings until they''re strong. It''s sharing your knowledge, experience and encouragement to help someone else grow, and being humble enough to learn from those ahead of you too. Mentors help others find their own path.', 'Too much, and mentorship can become control or ego: needing to be the expert, or shaping someone in your image instead of helping them become themselves.', 'Without mentorship, people learn everything the hard way. You may feel you have nothing to teach, or have no one to learn from. Everyone knows something someone else needs.', '{"Connection","Mind"}', '{"openness"}', '{"learning","patience"}', '{"guiding","coaching"}'),
  ('openness', 'Openness', 'Air', 'An open window: letting new air in.', 'Openness is the door left ajar for the unexpected guest. It welcomes new ideas, people and experiences without needing to control them. In plain terms: being willing to consider other views, try new things and let yourself be changed. Openness keeps life fresh and relationships alive.', 'Too much, and openness becomes a door with no frame. You might take in every opinion and lose your own, or let in what harms you. An open mind still needs a centre.', 'Without openness, life narrows to the familiar. New ideas feel threatening and differences dangerous. Closing up often follows hurt. Opening again, a crack at a time, is a brave and gentle practice.', '{"Mind","Heart"}', '{"boundaries"}', '{"curiosity","trust"}', '{"receptiveness","open-heartedness"}'),
  ('reason', 'Reason', 'Air', 'Thinking things through.', 'Reason is a well-drawn map: it shows the terrain clearly so you can choose your path. It''s weighing evidence, thinking critically, and reaching conclusions you can explain. Reason helps you make good decisions, see through manipulation, and solve problems.', 'Too much, and reason can dismiss feelings, intuition and the things that can''t be measured. You may overthink, argue to win, or use logic to avoid what you feel. Not everything that matters can be proven.', 'Without reason, decisions can feel impulsive or swayed by whoever is loudest. You may struggle to think clearly when emotions run high. Reason is a skill, and it strengthens with practice.', '{"Mind"}', '{"intuition"}', '{"clarity","learning"}', '{"logic","rationality"}'),
  ('self-awareness', 'Self-awareness', 'Air', 'Seeing yourself clearly, and kindly.', 'Self-awareness is a clear mirror in good light. It''s knowing your patterns, triggers, strengths and blind spots, and noticing what''s happening inside you as it happens. Self-awareness gives you choice: you can''t change what you can''t see.', 'Too much, and self-awareness can become self-absorption or endless analysis. You may overthink every feeling, or know your patterns perfectly but never change them. Insight without action can become a comfortable loop.', 'Without self-awareness, life can feel like it keeps happening to you. The same conflicts repeat and reactions feel automatic. Often others see what we can''t, if we''re willing to ask.', '{"Mind","Spirit"}', '{"compassion"}', '{"honesty","presence"}', '{"self-insight","introspection"}'),
  ('storytelling', 'Storytelling', 'Air', 'Making meaning through the stories we share.', 'Storytelling is a fire in the dark with faces gathered round. It''s how we make sense of life, pass on wisdom, and feel less alone. Telling your story, and listening to others'', builds understanding, connection and meaning.', 'Too much, and storytelling can bend the truth, polishing your own story until it hides what really happened. You may get so caught in a narrative that you can''t see it any other way.', 'Without storytelling, experiences stay unspoken and meaning stays hidden. You may feel your story doesn''t matter, or keep it to yourself. Every life is a story worth telling.', '{"Play","Connection"}', '{"truth"}', '{"creativity","communication"}', '{"narrative","yarn-spinning"}'),
  ('truth', 'Truth', 'Air', 'Seeking what''s real, even when it''s hard.', 'Truth is the morning light after a long night of shadows. It''s wanting to know what''s really so, about the world, others and yourself, and being willing to face it. Truth sets things on solid ground, even when it''s uncomfortable.', 'Too much, and truth can become a weapon: harsh honesty that wounds, or certainty that leaves no room for other views. Truth without care can push people away instead of bringing clarity.', 'Without truth, life gets built on stories that don''t hold. You may avoid hard facts, believe what''s comforting, or feel unsure what''s real. Living with untruth often costs more than the truth would.', '{"Mind","Spirit"}', '{"compassion"}', '{"honesty","courage"}', '{"veracity","reality"}'),
  ('abundance', 'Abundance', 'Ether', 'Living from enough, not from lack.', 'Abundance is a fruit tree heavy with more than it can hold. It''s seeing what''s present rather than only what''s missing, and trusting there''s enough love, opportunity and goodness to go around. Abundance opens the heart to give and receive freely.', 'Too much, and abundance thinking can ignore real need and inequality. It can turn into blame ("you just didn''t manifest enough"), or into careless spending and consumption.', 'Without abundance, life feels tight, competitive and scarce. You may fear there''s never enough, of money, time, love or recognition. Scarcity often comes from real hardship, and deserves compassion.', '{"Spirit","Home & Earth"}', '{"stewardship"}', '{"gratitude","generosity"}', '{"plenty","enoughness"}'),
  ('alchemy', 'Alchemy', 'Ether', 'Turning what life gives you into gold.', 'Alchemy is the old art of turning lead into gold, made personal. It''s taking hardship, heartbreak and ordinary days and transforming them into wisdom, art, strength and meaning. An alchemist doesn''t wait for a perfect life; they keep turning the life they have into the dream they want to be living.', 'Too much, and alchemy can push to make everything meaningful, rushing past pain to find the lesson. Some things are simply hard, and need grieving before they''re transformed.', 'Without alchemy, hardship stays heavy and unused. You may feel your struggles were wasted, or that your life is something that just happened to you. Every experience can become material for growth.', '{"Spirit","Purpose"}', '{"acceptance"}', '{"transformation","resilience"}', '{"transmutation","inner alchemy"}'),
  ('authenticity', 'Authenticity', 'Ether', 'Letting your outside match the light within.', 'Authenticity is being the same shape inside and out, like a tree that grows the way its seed intended. It''s living from your own values and voice rather than borrowed ones. Plainly: expressing who you truly are, and making choices that fit that truth, even when it''s not what''s expected. It lets others meet the real you.', 'Too much, and "being myself" can become a reason not to grow, or not to consider others. Identity hardens into a fixed story. The truest self is still becoming.', 'Without authenticity, life can feel like a costume. You might play roles to be liked, safe or successful, and feel strangely absent from your own life. The mask usually went on for good reasons. Taking it off is gentle, gradual work.', '{"Spirit","Heart"}', '{"adaptability"}', '{"courage","honesty"}', '{"genuineness","realness"}'),
  ('beauty', 'Beauty', 'Ether', 'Noticing, and making, what moves you.', 'Beauty is morning light through a dewy web. It''s noticing what''s lovely, in nature, art, people and small details, and bringing beauty into the world through how you live and create. Beauty feeds the spirit.', 'Too much, and beauty can become surface: judging by appearances, chasing perfection, or feeling worthless when you don''t match an ideal. Beauty becomes a burden when it''s about being seen as beautiful.', 'Without beauty, life can feel grey and functional. You may rush past what''s lovely, or stop making space for art and nature. Beauty is often there, waiting to be noticed.', '{"Spirit","Play"}', '{"acceptance"}', '{"wonder","creativity"}', '{"loveliness","aesthetics"}'),
  ('contribution', 'Contribution', 'Ether', 'Leaving things better than you found them.', 'Contribution is adding your stone to a cairn that guides travellers home. It''s knowing your life adds something to others, to your community and to the world. Contribution can be big or small: a kind act, a good piece of work, raising a child, planting a tree.', 'Too much, and contribution can become a measure of worth: never feeling you''ve done enough, always needing to prove your impact. You may forget that simply being is also a gift.', 'Without contribution, life can feel purposeless or self-centred. You may wonder whether your life matters. It does, and small contributions often matter most.', '{"Purpose","Connection"}', '{"rest"}', '{"service","meaning"}', '{"making a difference","impact"}'),
  ('grace', 'Grace', 'Ether', 'Ease and mercy, given and received.', 'Grace is rain that falls on every garden, deserving or not. It''s mercy you didn''t earn, kindness given freely, and the ease of moving through life with dignity. Grace forgives, softens, and lets people begin again.', 'Too much, and grace can excuse what shouldn''t be excused. Offering endless second chances can let harm continue, or leave you carrying others'' responsibilities.', 'Without grace, life becomes strict and unforgiving. You may hold yourself and others to impossible standards, with no room for mistakes. Learning to receive grace is often harder than giving it.', '{"Spirit","Heart"}', '{"integrity"}', '{"forgiveness","gratitude"}', '{"graciousness","elegance"}'),
  ('gratitude', 'Gratitude', 'Ether', 'Finding the sacred in the ordinary.', 'Gratitude is sunlight noticed through the leaves on an ordinary afternoon. It sees what is already given: warmth, a kind word, a body that carried you through the day. Plainly: recognising and appreciating the good in your life, big or small. It doesn''t deny difficulty; it widens the view so difficulty isn''t all there is.', 'Forced, gratitude becomes a way to skip over pain: "I should be grateful" said over real grief or injustice. It can turn into an obligation that silences what needs to be felt or changed.', 'Without gratitude, what''s missing fills the frame and what''s here goes unseen. This often grows in hard seasons, and it''s understandable. Even a small, honest thank-you can let a little light back in.', '{"Spirit"}', '{"honesty"}', '{"presence","wonder"}', '{"thankfulness","appreciation"}'),
  ('harmony', 'Harmony', 'Ether', 'Things fitting together as they should.', 'Harmony is many instruments playing one song. It''s balance within yourself, ease between people, and a sense that the parts of life fit together. Harmony doesn''t mean everyone is the same; it means differences work together beautifully.', 'Too much, and harmony can become conflict-avoidance: keeping everything smooth at the cost of truth. Every note forced into line can lose the music.', 'Without harmony, life can feel jarring and disjointed, at home, at work, or inside yourself. You might feel constantly pulled in different directions. Small adjustments can restore a lot of harmony.', '{"Spirit","Connection"}', '{"honesty"}', '{"peace","fairness"}', '{"concord","balance"}'),
  ('love', 'Love', 'Ether', 'The warm light that makes everything grow.', 'Love is the sun on a garden, warmth that helps life unfold. It''s care, delight and deep connection, given and received. In plain terms: wanting the good of another, and yourself, and acting on it with kindness, affection and presence. Love takes many forms: romantic, familial, friendship, love of place, love of life.', 'Too much, and love can tighten into possession, dependency or losing yourself in another. "I love you" can become "I need you to be what I want." The sun that never sets scorches the garden.', 'Without love, life grows cold and lonely. You might feel unlovable, or keep love at arm''s length to stay safe. The longing for love is itself a sign you''re made for it. Love often begins again in small ways: a kind word, a gentle hand, a moment of self-care.', '{"Connection","Heart"}', '{"freedom"}', '{"compassion","commitment"}', '{"affection","tenderness"}'),
  ('meaning', 'Meaning', 'Ether', 'The golden thread that ties your days together.', 'Meaning is the star you steer by, the sense that your life is part of something that matters. It turns ordinary moments into chapters of a larger story. Put simply: knowing why you do what you do, and feeling connected to purposes beyond yourself. Meaning can be found in love, work, faith, creativity or service.', 'Too much, and the search for meaning can weigh everything down. Every choice must be significant, every day purposeful. The simple joys get lost beneath the need for depth.', 'Without meaning, life can feel like going through motions. You might ask "what''s the point?" more often than you''d like. That question is itself a sign of a soul reaching for something. Meaning often reappears in small, honest acts of love.', '{"Spirit","Purpose"}', '{"playfulness"}', '{"wonder","gratitude"}', '{"significance","depth"}'),
  ('mystery', 'Mystery', 'Ether', 'Making peace with not knowing.', 'Mystery is a path disappearing into mist. It''s being at ease with what can''t be explained, predicted or controlled. Mystery keeps life alive with possibility, and humbles the mind with how much is still unknown.', 'Too much, and mystery can become vagueness or avoidance, using "who can know?" to dodge questions that do have answers. Not everything is meant to stay a mystery.', 'Without mystery, life can feel over-explained and controlled. You may need certainty about everything, or feel anxious when things are unclear. Learning to live with not knowing brings a quiet freedom.', '{"Spirit","Mind"}', '{"clarity"}', '{"wonder","curiosity"}', '{"the unknown","enigma"}'),
  ('presence', 'Presence', 'Ether', 'Being fully here, in body, mind and soul.', 'Presence is the still point at the centre of the turning wheel. It''s arriving in your own life: tasting the food, hearing the person, feeling your feet on the ground. In plain terms: giving your full attention to this moment, instead of living in worry, memory or a screen. Presence doesn''t change what''s happening; it changes whether you''re there for it.', 'Taken too far, "just be here" can become a way to avoid the future or the past. Plans, consequences and old wounds get set aside in the name of the present moment. Stillness becomes a way around things rather than through them.', 'Without presence, life happens somewhere else: in worry, memory or a screen. Days blur. That absence often protects you from something the present holds. Gently coming back, even for a breath, is the practice.', '{"Mind"}', '{"responsibility"}', '{"gratitude","acceptance"}', '{"mindfulness","attention","awareness"}'),
  ('ritual', 'Ritual', 'Ether', 'Making the ordinary sacred.', 'Ritual is lighting a candle at the same hour each evening. It''s intentional practices that mark time, bring meaning and help us move through life''s transitions. Rituals turn routine into reverence: morning tea, a weekly walk, a ceremony for a new beginning.', 'Too much, and ritual can become rigid or superstitious, a routine you can''t break without anxiety. Ritual without meaning becomes empty habit.', 'Without ritual, days can blur together and life''s big moments pass without being marked. You may feel rushed, unanchored, or unsure how to honour endings and beginnings.', '{"Spirit","Home & Earth"}', '{"freedom"}', '{"presence","tradition"}', '{"ceremony","rite"}'),
  ('sovereignty', 'Sovereignty', 'Ether', 'Belonging to yourself while you belong with others.', 'Sovereignty is a lighthouse: open, warm, shining for others, and never moved by the waves. It''s living from your own centre, making choices that are truly yours, and staying open-hearted without leaving yourself behind. Sovereign people can love deeply and stay whole.', 'Too much, and sovereignty can harden into isolation or control: needing no one, answering to no one, or confusing independence with strength. A kingdom of one can be lonely.', 'Without sovereignty, you may feel ruled by others'' moods, expectations or needs. Your choices might follow what keeps others comfortable rather than what''s true for you. Reclaiming yourself is gentle, steady work.', '{"Spirit","Heart"}', '{"love"}', '{"boundaries","authenticity"}', '{"self-possession","self-governance"}'),
  ('spirituality', 'Spirituality', 'Ether', 'A living relationship with what is greater.', 'Spirituality is a window left open to the night sky. It''s a felt connection with something larger than yourself, whether that''s God, nature, the universe, love, or the mystery of being alive. Spirituality can live in prayer, meditation, ritual, art, or a quiet walk at dawn.', 'Too much, and spirituality can float away from everyday life. It can become a way of bypassing pain ("everything happens for a reason"), or a sense of being above others. Spirit needs a body and a life to live in.', 'Without spirituality, life can feel flat or meaningless, as if there''s nothing beyond the daily grind. You might long for something you can''t name. Spirituality doesn''t need a religion; it often begins with simple wonder.', '{"Spirit"}', '{"groundedness"}', '{"presence","wonder"}', '{"soulfulness","inner life"}'),
  ('transcendence', 'Transcendence', 'Ether', 'Reaching beyond the small self.', 'Transcendence is a mountain-top view where your worries suddenly look small. It''s moments of going beyond your usual sense of self: in awe, deep meditation, music, love or service. Transcendence brings perspective, peace and a sense of something vast.', 'Too much, and transcendence can become escape: always reaching for the next peak, disconnecting from everyday life and its responsibilities. You still have to come down the mountain.', 'Without transcendence, life can feel confined to small worries and daily routines. You may never feel lifted beyond yourself. Such moments often come when we least expect them.', '{"Spirit"}', '{"groundedness"}', '{"spirituality","wonder"}', '{"rising above","the beyond"}'),
  ('trust', 'Trust', 'Ether', 'Leaning back into life, believing you''ll be caught.', 'Trust is the bridge you walk across without testing every plank. It''s believing in yourself, in others, or in life''s unfolding enough to let go of control. Plainly: relying on someone or something with an open heart, and on your own ability to handle what comes. Trust makes closeness, risk and rest possible.', 'Too much, and trust becomes naivety. You might ignore warning signs, or give your heart to people who haven''t earned it. Blind trust can lead you onto broken bridges.', 'Without trust, life becomes guarded and exhausting. You check, control and brace for disappointment. Distrust is usually learned for good reasons. Small experiences of safety can slowly teach the heart that some bridges hold.', '{"Spirit","Connection"}', '{"wisdom"}', '{"openness","patience"}', '{"faith","confidence in others"}'),
  ('unity', 'Unity', 'Ether', 'Knowing we''re part of one whole.', 'Unity is a single ocean made of countless drops. It''s sensing that we are deeply connected, to each other, to nature, to all of life. Unity grows compassion, because hurting another starts to feel like hurting ourselves.', 'Too much, and unity can erase difference, pushing everyone to agree and be the same. Your individual voice can get lost in the whole.', 'Without unity, life can feel divided: us and them, me and the world. You may feel separate, alone or at odds with others. Shared moments of connection can bridge that gap.', '{"Spirit","Connection"}', '{"authenticity"}', '{"love","community"}', '{"oneness","solidarity"}'),
  ('wisdom', 'Wisdom', 'Ether', 'Knowledge that has been lived, and softened by time.', 'Wisdom is the old tree that has weathered many seasons. It knows when to bend, when to hold, when to speak and when to stay quiet. Literally: using knowledge, experience and understanding to make good judgements, especially in complex situations. Wisdom comes from living, reflecting and learning from both joy and pain.', 'Too much, and wisdom can become aloofness, or the belief that you always know best. Advice flows but listening stops. The old tree can forget it was once a sapling.', 'Without wisdom, life can feel like repeating the same lessons. You might act on impulse or others'' opinions rather than your own understanding. Wisdom grows from reflection: pausing to ask what life has been teaching you.', '{"Spirit","Mind"}', '{"humour"}', '{"learning","presence"}', '{"good judgement","sagacity"}'),
  ('wonder', 'Wonder', 'Ether', 'Seeing the world as if for the first time.', 'Wonder is looking up at the night sky and feeling both tiny and part of everything. It''s the gasp at a sunrise, the child''s "whoa" at a beetle. In plain terms: a sense of amazement and awe at life''s mystery and beauty. Wonder reminds you that the world is bigger than your worries.', 'Too much, and wonder can drift into escapism: always gazing at the stars and never at the ground. Life''s practical needs can slip away while you''re lost in the marvel.', 'Without wonder, life turns ordinary and flat. Everything seems known and explained. Busy-ness and worry are often wonder''s quiet thieves. Slowing down, even for a minute outside, can let it back in.', '{"Spirit","Play"}', '{"clarity"}', '{"curiosity","presence"}', '{"amazement","awe of heart"}')
